# Expand extraction bootstrap for full library\n\nimport glob\nfrom app.extractors.authentic_snes_extractor import AuthenticSNESExtractor\n\nfor rom_path in glob.glob('ROM_SOURCE/unzipped/*.sfc') + glob.glob('ROM_SOURCE/unzipped/*.smc'):\n    extractor = AuthenticSNESExtractor(Path(rom_path))\n    game_id = extractor.identify_game()\n    if game_id in TOP_50_SNES_GAMES:  # Prioritize\n        sprites = extractor.extract_sprites(game_id, TOP_50_SNES_GAMES[game_id])\n        audio = extractor.extract_audio(game_id, TOP_50_SNES_GAMES[game_id])\nextractor.save_manifest()
